from pathlib import Path
import json,re,html
r=Path(__file__).resolve().parent.parent;d=r/'tools/testes32';qs=json.loads((d/'data.json').read_text());esc=html.escape
assert len(qs)==32
subjects=list(dict.fromkeys(q['subject'] for q in qs))
for subject in subjects:
 group=[q for q in qs if q['subject']==subject]
 assert len(group)==8 and sum(q['kind']=='Atual' for q in group)==6 and sum(q['kind']=='Revisão' for q in group)==2
for q in qs:assert len(q['options'])==5 and len(set(q['options']))==5 and 0<=q['correct']<5
base=(r/'index.html').read_text();styles=re.findall(r'<style>(.*?)</style>',base,re.S);scripts=re.findall(r'<script>(.*?)</script>',base,re.S)
nav=re.search(r'<nav class="page-tabs" aria-label="Cadernos de estudo">.*?</nav>',base,re.S).group();nav=re.sub(r' aria-current="page"','',nav)
link='<a href="testes-32.html">Simulado · 32 testes</a>'
if 'href="testes-32.html"' not in nav:nav=nav.replace('</nav>',link+'</nav>')
nav=nav.replace('href="testes-32.html"','href="testes-32.html" aria-current="page"')
css=(r/'tools/quimica/style.css').read_text()+'''
.test-card fieldset{border:0;margin:0;padding:0;min-width:0}.test-card legend{font-size:1.05rem;line-height:1.7;margin:0 0 20px;padding:0;width:100%}.option{display:flex;gap:12px;align-items:baseline;padding:12px;border:1px solid #d7dace;border-radius:8px;margin:8px 0;cursor:pointer}.option:has(input:checked){background:#e5eee6;border-color:#243f35}.option input{accent-color:#243f35;flex-shrink:0}.feedback{font-weight:600;color:#243f35;min-height:1em}.test-card{break-inside:avoid}.subject-heading{margin:36px 0 20px}.actions{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}.result{padding:20px;border:2px solid #243f35;border-radius:12px}.key-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(100px,1fr));gap:10px}.key-grid a{padding:10px;background:#e5eee6;color:#243f35;border-radius:6px}.solution-card li{margin:12px 0}.rationale{line-height:1.7}.katex-display{overflow-x:auto;overflow-y:hidden}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #b45c30;outline-offset:3px}@media print{.question-card,.solution-card{break-after:auto;margin-bottom:18px}.answer-space,.question-card:first-child .answer-space{height:70px;margin-top:10px}.subject-heading{break-after:avoid}.actions,.feedback,.result,.question-jumps{display:none!important}.option{padding:5px;border:0}.test-card{page-break-inside:avoid}.option:has(input:checked){background:transparent}.option input{appearance:none;border:1px solid #555;width:10px;height:10px}.key-grid a{background:none}.calibration{display:none!important}}@media(max-width:600px){.option{padding:10px 8px}.question-card{padding:20px}.katex{font-size:1em}}
'''
body=[];solutions=[]
for si,subject in enumerate(subjects):
 body.append(f'<h2 class="subject-heading" id="disciplina-{si}">{esc(subject)} <small>· 8 testes</small></h2>')
 for q in (q for q in qs if q['subject']==subject):
  i=q['id'];tag=f"{q['kind']} · {q['topic']}";opts=''.join(f'<label class="option"><input type="radio" name="q{i}" value="{j}"><span><strong>{chr(65+j)})</strong> {esc(o)}</span></label>' for j,o in enumerate(q['options']))
  body.append(f'<article class="question-card test-card" id="teste-{i}" data-id="{i}" data-answer="{q["correct"]}" data-subject="{esc(subject)}"><p class="eyebrow">{esc(tag)}</p><fieldset><legend><strong>Teste {i:02d}.</strong> {esc(q["prompt"])}</legend>{opts}</fieldset><p class="feedback" aria-live="polite"></p><div class="answer-space">Cálculos e raciocínio:</div></article>')
  steps=''.join(f'<li>{esc(s)}</li>' for s in q['steps'])
  solutions.append(f'<article class="solution-card" id="solucao-{i}"><p class="eyebrow">{esc(subject)} · {esc(tag)}</p><h3>Teste {i:02d} · Alternativa {chr(65+q["correct"])}</h3><p class="answer-result">{esc(q["options"][q["correct"]])}</p><ol>{steps}</ol><p class="pitfall"><strong>Atenção:</strong> {esc(q["tip"])}</p></article>')
jumps=''.join(f'<a href="#disciplina-{i}">{esc(s)}</a>' for i,s in enumerate(subjects))
key=''.join(f'<a href="#solucao-{q["id"]}">{q["id"]:02d} · {chr(65+q["correct"])}</a>' for q in qs)
page='''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>32 testes · Álgebra, passo a passo</title><meta name="description" content="32 testes de Matemática, Química, Física e Aritmética, com cinco alternativas, correção por disciplina e gabarito comentado."><style>'''+styles[0]+'</style><style>'+css+'</style><script>'+scripts[0]+'</script><script>'+scripts[1]+'''</script></head><body><header><div class="masthead"><span>Álgebra, passo a passo</span><span>1ª série · Ensino médio</span></div>'''+nav+'''<div class="hero"><div><p class="eyebrow">Revisão para os testes · 30/10/2026</p><h1>32 testes.<br><em>Quatro disciplinas.</em></h1><p class="intro">Matemática, Química, Física e Aritmética. Seis questões atuais e duas de revisão em cada disciplina.</p></div><aside class="exam-summary"><strong>32</strong><p>questões objetivas<br>cinco alternativas por teste</p><span>24 atuais + 8 de revisão</span></aside></div><div class="mode-switch" role="group" aria-label="Visualização"><button id="show-exam" aria-pressed="true" aria-controls="exam">Testes</button><button id="show-answers" aria-pressed="false" aria-controls="answers">Gabarito comentado</button></div></header><main><section id="exam"><div class="section-top"><h2>Marque uma alternativa.</h2><button class="utility" id="print-exam">Imprimir testes</button></div><p class="instructions">Resolva no papel e marque apenas uma alternativa em cada teste. Todas as questões têm o mesmo peso. Clique em “Corrigir respostas” ao terminar. As respostas permanecem apenas nesta página e são perdidas ao recarregá-la. Os dados necessários estão nos enunciados.</p><noscript>Ative JavaScript para renderizar as fórmulas, corrigir respostas e abrir o gabarito.</noscript><div class="print-identity">Nome: ____________________________________ Data: ____/____/______</div><nav class="question-jumps" aria-label="Disciplinas">'''+jumps+'</nav><form id="test-form">'+''.join(body)+'''</form><div class="actions"><button class="utility" id="correct">Corrigir respostas</button><button class="utility" id="clear">Limpar respostas</button></div><div id="result" class="result" role="status" tabindex="-1" hidden></div></section><section id="answers" hidden><div class="section-top"><h2>Gabarito comentado.</h2><button class="utility" id="print-answers">Imprimir gabarito</button></div><div class="key-grid">'''+key+'</div>'+''.join(solutions)+'''</section><details class="calibration"><summary>Conteúdos e referências</summary><div class="rationale"><p>Questões inéditas, calibradas pelos testes 45–76 das 16 fotos fornecidas: cinco alternativas, cálculos com etapas, leitura de afirmações e algoritmos. As alternativas marcadas nos originais não foram tratadas como gabarito. A equivalência de dificuldade é uma estimativa pedagógica.</p><p>Conteúdo atual: circular 148/2026. Matemática: três itens de exponenciais e três de polígonos inscritos/circunscritos. Química: dois de hidrocarbonetos/combustíveis, dois de tipos de reação e dois de funções inorgânicas. Física: dois de lançamento horizontal, dois de calorimetria/mudança de estado e dois de blocos com tração. Aritmética: seis itens de logaritmos.</p><p>Revisão intercalada: Matemática — função quadrática e inequação racional; Química — separação de misturas e estrutura atômica; Física — movimento uniforme e dinâmica com conversões; Aritmética — PA e PG com algoritmo. A seleção usa conteúdos anteriores da primeira série e os exemplos fornecidos. Aritmética é o nome do itinerário da escola; PA e PG pertencem à área de Matemática. A distribuição por semestre varia conforme a escola: estes rótulos indicam revisão em relação à circular, não uma sequência semestral oficial de 2026.</p><p>Referências curriculares públicas: <a href="https://efape.educacao.sp.gov.br/curriculopaulista/ensino-medio/">Currículo Paulista — Ensino Médio</a>; <a href="https://efape.educacao.sp.gov.br/curriculopaulista/wp-content/uploads/pdfs/EM_PR_MT_01_Vol1_VP.pdf">material de apoio paulista: sequências, PA e PG</a>; <a href="https://www.educacao.sp.gov.br/a2sitebox/arquivos/documentos/783.pdf">referência curricular paulista de Matemática, primeira série</a>; <a href="https://efape.educacao.sp.gov.br/curriculopaulista/wp-content/uploads/download/habilidades-essenciais-ensino%20medio%202021/Habilidades%20Essenciais%20de%20F%C3%ADsica%20-%20EM%202021.pdf">habilidades essenciais de Física: primeira série, cinemática e dinâmica</a>. Também foi consultada a <a href="https://efape.educacao.sp.gov.br/curriculopaulista/wp-content/uploads/2023/01/2s%C3%A9rie-Professor-CNT-1sem-parte1.pdf">retomada oficial dos modelos atômicos trabalhados na primeira série</a>. Os materiais de apoio históricos orientam a revisão e não substituem o calendário da escola.</p></div></details></main><footer>Material de estudo · 32 questões inéditas · Fotos originais e dados pessoais não publicados.</footer><script>'''+(d/'app.js').read_text()+'</script></body></html>'
(r/'testes-32.html').write_text(page)
for p in r.glob('*.html'):
 t=p.read_text()
 def insert(m):
  n=m.group();return n if 'href="testes-32.html"' in n else n.replace('</nav>',link+'</nav>')
 out=re.sub(r'<nav class="page-tabs" aria-label="Cadernos de estudo">.*?</nav>',insert,t,flags=re.S)
 if out!=t:p.write_text(out)
print('32 testes: 8 por disciplina, 6 atuais + 2 revisão; 160 alternativas; navegação integrada.')
